import { Router, Request, Response } from "express";
import { CreateProjectUseCase } from "../application/CreateProjectUseCase";
import { IProjectRepository } from "../domain/IProjectRepository";

export class ProjectController {
  private router: Router;
  private createProjectUseCase: CreateProjectUseCase;

  constructor(projectRepository: IProjectRepository) {
    this.router = Router();
    this.createProjectUseCase = new CreateProjectUseCase(projectRepository);
    this.setupRoutes();
  }

  private setupRoutes(): void {
    this.router.post("/projects", (req: Request, res: Response) => {
      try {
        const { name } = req.body as { name?: string };
        if (!name) {
          res.status(400).json({ error: "Name is required" });
          return;
        }
        const project = this.createProjectUseCase.execute(name);
        res.status(201).json(project);
      } catch (error) {
        const message = error instanceof Error ? error.message : "Unknown error";
        res.status(400).json({ error: message });
      }
    });
  }

  getRouter(): Router {
    return this.router;
  }
}

=====SOURCE-END=====

